335	    private static int webSocketConnection(String url, List<String> args, CLIConnectionFactory factory) throws Exception {
336	        LOGGER.fine(() -> "Trying to connect to " + url + " via plain protocol over WebSocket");
337	        class CLIEndpoint extends Endpoint {
338	            @Override
339	            public void onOpen(Session session, EndpointConfig config) {}
340	        }
341	
342	        class Authenticator extends ClientEndpointConfig.Configurator {
343	            @Override
344	            public void beforeRequest(Map<String, List<String>> headers) {
345	                if (factory.authorization != null) {
346	                    headers.put("Authorization", List.of(factory.authorization));
347	                }
348	            }
349	        }
350	
351	        ClientManager client = ClientManager.createClient(JdkClientContainer.class.getName()); // ~ ContainerProvider.getWebSocketContainer()
352	        client.getProperties().put(ClientProperties.REDIRECT_ENABLED, true); // https://tyrus-project.github.io/documentation/1.13.1/index/tyrus-proprietary-config.html#d0e1775
353	        if (factory.noCertificateCheck) {
354	            SSLContext sslContext = SSLContext.getInstance("TLS");
355	            sslContext.init(null, new TrustManager[] {new NoCheckTrustManager()}, new SecureRandom());
356	            SslEngineConfigurator sslEngineConfigurator = new SslEngineConfigurator(sslContext);
357	            sslEngineConfigurator.setHostnameVerifier((s, sslSession) -> true);
358	            client.getProperties().put(ClientProperties.SSL_ENGINE_CONFIGURATOR, sslEngineConfigurator);
359	        }
360	        Session session = client.connectToServer(new CLIEndpoint(), ClientEndpointConfig.Builder.create().configurator(new Authenticator()).build(), URI.create(url.replaceFirst("^http", "ws") + "cli/ws"));
361	        PlainCLIProtocol.Output out = new PlainCLIProtocol.Output() {
362	            @Override
363	            public void send(byte[] data) throws IOException {
364	                session.getBasicRemote().sendBinary(ByteBuffer.wrap(data));
365	            }
366	
367	            @Override
