385	    private static int plainHttpConnection(String url, List<String> args, CLIConnectionFactory factory)
386	            throws GeneralSecurityException, IOException, InterruptedException {
387	        LOGGER.log(FINE, "Trying to connect to {0} via plain protocol over HTTP", url);
388	        if (factory.noCertificateCheck) {
389	            SSLContext sslContext = SSLContext.getInstance("TLS");
390	            sslContext.init(null, new TrustManager[] {new NoCheckTrustManager()}, new SecureRandom());
391	            HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
392	            HttpsURLConnection.setDefaultHostnameVerifier((s, sslSession) -> true);
393	        }
