395	        try (ClientSideImpl connection = new ClientSideImpl(new PlainCLIProtocol.FramedOutput(streams.getOutputStream()))) {
396	            connection.start(args);
397	            InputStream is = streams.getInputStream();
398	            if (is.read() != 0) { // cf. FullDuplexHttpService
399	                throw new IOException("expected to see initial zero byte; perhaps you are connecting to an old server which does not support -http?");
